// Apply saved edits (cams/edits items) to a workbook buffer. Returns {buf,applied:[ix],skipped:[{ix,reason}]}
function xlApply(buf,items){
  const ents=zipRead(buf),map=new Map(ents.map(e=>[e.name,e])),get=n=>{const e=map.get(n);return e?zipData(e).toString('utf8'):null};
  const paths=xlSheetPaths(get),SS=xlShared(get),mods=new Map(),applied=[],skipped=[],grown={};
  const by={};items.forEach((e,ix)=>{(by[e.sh]=by[e.sh]||[]).push({ix,e})});
  for(const sh of Object.keys(by)){
    const P=paths[sh];if(!P){by[sh].forEach(o=>skipped.push({ix:o.ix,reason:'the sheet "'+sh+'" was not found'}));continue}
    const relN=P.replace(/([^/]+)$/,'_rels/$1.rels'),rel=get(relN),tables=[];
    if(rel)for(const m of rel.matchAll(/<Relationship\b[^>]*>/g)){const t=/\bTarget="([^"]*)"/.exec(m[0]),ty=/\bType="([^"]*)"/.exec(m[0]);if(t&&ty&&/\/table$/.test(ty[1])){const tp=t[1].startsWith('/')?t[1].slice(1):'xl/'+t[1].replace(/^\.\.\//,'');const tx=get(tp);if(tx)tables.push({name:tp,text:tx})}}
    // order: edits and deletes first, then added rows in the order they were added
    const list=by[sh].filter(o=>o.e.t!=='a').concat(by[sh].filter(o=>o.e.t==='a'));
    const r=patchSheet(get(P),SS,list,tables);
    if(r.grew)grown[sh]=r.grew;
    mods.set(P,r.xml);Object.keys(r.extra).forEach(k=>mods.set(k,r.extra[k]));applied.push(...r.applied);skipped.push(...r.skipped)}
  if(!applied.length)return{buf:null,applied,skipped};
  if(Object.keys(grown).length)for(const P of Object.values(paths)){const t=mods.has(P)?mods.get(P):get(P);if(t==null)continue;const nt=growRefs(t,grown,false);if(nt!==t)mods.set(P,nt)}
  let wbx=get('xl/workbook.xml');if(Object.keys(grown).length)wbx=growRefs(wbx,grown,true);
  if(/<calcPr\b/.test(wbx)){if(!/fullCalcOnLoad=/.test(wbx))wbx=wbx.replace(/<calcPr\b/,'<calcPr fullCalcOnLoad="1"')}
  else{const at=['<oleSize','<customWorkbookViews','<pivotCaches','<smartTagPr','<smartTagTypes','<webPublishing','<fileRecoveryPr','<webPublishObjects','<extLst','</workbook>'].map(k=>wbx.indexOf(k)).filter(i=>i>=0).sort((a,b)=>a-b)[0];wbx=wbx.slice(0,at)+'<calcPr fullCalcOnLoad="1"/>'+wbx.slice(at)}
  mods.set('xl/workbook.xml',wbx);
  const out=ents.map(e=>{if(!mods.has(e.name))return e;const d=Buffer.from(mods.get(e.name),'utf8'),z=zlib.deflateRawSync(d);return Object.assign({},e,{method:8,raw:z,crc:crc32(d),csize:z.length,usize:d.length})});
  const nb=zipWrite(out);
  // check: the new file must read back and every changed part must still be well-formed at its ends
  const chk=zipRead(nb);for(const e of chk){const d=zipData(e);if(crc32(d)!==e.crc)throw new Error('Internal check failed for '+e.name+'.');if(mods.has(e.name)&&!/<\/(worksheet|workbook|table)>\s*$/.test(d.toString('utf8')))throw new Error('Internal check failed for '+e.name+'.')}
  return{buf:nb,applied,skipped}}

// ---- OneDrive / SharePoint source for the monthly workbook ----
let CFG={};try{CFG=JSON.parse(fs.readFileSync(path.join(DATA,'config.json'),'utf8'))}catch(e){}
const cfg=k=>process.env[k]||CFG[k]||'';
const b64u=s=>Buffer.from(s).toString('base64').replace(/=+$/,'').replace(/\//g,'_').replace(/\+/g,'-');
async function graphToken(){
  const r=await fetch(`https://login.microsoftonline.com/${encodeURIComponent(cfg('MS_TENANT_ID'))}/oauth2/v2.0/token`,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},signal:AbortSignal.timeout(20000),
    body:new URLSearchParams({client_id:cfg('MS_CLIENT_ID'),client_secret:cfg('MS_CLIENT_SECRET'),scope:'https://graph.microsoft.com/.default',grant_type:'client_credentials'})});
  const j=await r.json();if(!r.ok)throw new Error('Microsoft sign-in failed: '+(j.error_description||j.error||r.status));return j.access_token;
}
async function fetchWorkbook(L){
  const link=L||cfg('ONEDRIVE_LINK');if(!link)throw new Error('No OneDrive link is set on the server.');
  const tries=[],host=(()=>{try{return new URL(link).hostname}catch(e){return ''}})();
  if(cfg('MS_CLIENT_ID')&&cfg('MS_CLIENT_SECRET')&&cfg('MS_TENANT_ID')){
    tries.push(async()=>fetch('https://graph.microsoft.com/v1.0/shares/u!'+b64u(link)+'/driveItem/content',{headers:{Authorization:'Bearer '+await graphToken()},signal:AbortSignal.timeout(120000)}));
  }
  if(/(^|\.)(1drv\.ms|onedrive\.live\.com)$/.test(host))tries.push(()=>fetch('https://api.onedrive.com/v1.0/shares/u!'+b64u(link)+'/root/content',{signal:AbortSignal.timeout(120000)}));
  tries.push(()=>fetch(link+(link.includes('?')?'&':'?')+'download=1',{signal:AbortSignal.timeout(120000)}));
  let last='';
  for(const t of tries){
    try{
      const r=await t();if(!r.ok){last='HTTP '+r.status;continue}
      const buf=Buffer.from(await r.arrayBuffer());
      if(buf.length<4||buf[0]!==0x50||buf[1]!==0x4b){last='the link returned a web page, not the workbook (is it set to "anyone with the link can view"?)';continue}
      const cd=r.headers.get('content-disposition')||'',m=cd.match(/filename\*?=(?:UTF-8'')?"?([^";]+)/i);
      return{buf,name:cfg('ONEDRIVE_NAME')||(m&&decodeURIComponent(m[1]))||'CCDM_DB.xlsm',modified:r.headers.get('last-modified')||''};
    }catch(e){last=e.message}
  }
  throw new Error('Could not download the workbook: '+last);
}



// ---- Sign in to a personal OneDrive once (delegated, PKCE). No public link needed. ----
const TOKFILE=path.join(DATA,'ms_token.json');
const AUTHORITY=()=>`https://login.microsoftonline.com/${cfg('MS_AUTHORITY')||'consumers'}/oauth2/v2.0`;
const REDIRECT=()=>cfg('MS_REDIRECT')||`http://localhost:${PORT}/auth/callback`;
const PENDING=new Map(); // state -> code_verifier
let ACCESS={token:'',exp:0};
const delegated=()=>!!cfg('MS_CLIENT_ID')&&!cfg('MS_CLIENT_SECRET');
const loadTok=()=>{try{return JSON.parse(fs.readFileSync(TOKFILE,'utf8'))}catch(e){return null}};
async function tokenCall(params){
  const r=await fetch(AUTHORITY()+'/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},signal:AbortSignal.timeout(30000),body:new URLSearchParams(Object.assign({client_id:cfg('MS_CLIENT_ID'),scope:'offline_access Files.Read'},params))});
  const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error('Microsoft sign-in failed: '+(j.error_description||j.error||r.status));
  if(j.refresh_token)fs.writeFileSync(TOKFILE,JSON.stringify({refresh_token:j.refresh_token,saved:new Date().toISOString()}),{mode:0o600});
  ACCESS={token:j.access_token,exp:Date.now()+(j.expires_in-120)*1000};return ACCESS.token;
}
async function delegatedToken(){
  if(ACCESS.token&&Date.now()<ACCESS.exp)return ACCESS.token;
  const t=loadTok();if(!t)throw new Error('NOT_CONNECTED');
  return tokenCall({grant_type:'refresh_token',refresh_token:t.refresh_token});
}

// ---- Live file: one running workbook in OneDrive that is edited daily (shown on the /live page) ----
const LIVE_DEFAULT='CCDM/CCDM_DB_Live.xlsm';
function mkRemote(K){
  const S={at:0,meta:null,buf:null,mod:''};
function liveKind(){
  if(cfg(K.local)||(K.lfolder&&cfg(K.lfolder)))return'local';
  if(cfg(K.link))return'link';
  if(delegated())return'path';
  return'';
}
const folderMode=()=>!!K.fdef&&!cfg(K.file);
const folderPath=()=>(cfg(K.folder)||K.fdef).replace(/^\/+|\/+$/g,'');
const isXl=n=>/\.(xlsx|xlsm|xls)$/i.test(n)&&!n.startsWith('~$');
function localPick(){
  if(cfg(K.local))return cfg(K.local);
  const d=cfg(K.lfolder);let ents;try{ents=fs.readdirSync(d)}catch(e){throw new Error('Cannot open the folder '+d+' ('+(e.code==='ENOENT'?'it does not exist':e.message)+').')}
  let best=null;for(const n of ents){if(!isXl(n))continue;const f=path.join(d,n),st=fs.statSync(f);if(st.isFile()&&(!best||st.mtimeMs>best.t))best={f,t:st.mtimeMs}}
  if(!best)throw new Error('There is no Excel file in '+d+'.');return best.f}
const livePath=()=>(cfg(K.file)||K.def).replace(/^\/+|\/+$/g,'');
async function liveMeta(force){
  if(!force&&S.meta&&Date.now()-S.at<20000)return S.meta;
  const kind=liveKind();let m;
  if(kind==='local'){
    const f=localPick();let st;try{st=fs.statSync(f)}catch(e){throw new Error('Cannot open '+f+' ('+(e.code==='ENOENT'?'it does not exist':e.message)+').')}
    m={name:path.basename(f),modified:st.mtime.toISOString(),size:st.size,where:'OneDrive (synced folder)'};
  }else if(kind==='path'&&folderMode()){
    const t=await delegatedToken();
    const r=await fetch('https://graph.microsoft.com/v1.0/me/drive/root:/'+folderPath().split('/').map(encodeURIComponent).join('/')+':/children?$top=200',{headers:{Authorization:'Bearer '+t},signal:AbortSignal.timeout(30000)});
    const j=await r.json().catch(()=>({}));
    if(r.status===404)throw new Error('The '+K.what+' folder was not found in your OneDrive: '+folderPath());
    if(!r.ok)throw new Error('Could not read the '+K.what+' folder: '+((j.error&&(j.error.message||j.error.code))||r.status));
    const fl=(j.value||[]).filter(x=>x.file&&isXl(x.name)).sort((a,b)=>String(b.lastModifiedDateTime).localeCompare(String(a.lastModifiedDateTime)));
    if(!fl.length)throw new Error('There is no Excel file in the OneDrive folder '+folderPath()+'.');
    const x=fl[0];m={name:x.name,modified:x.lastModifiedDateTime||'',size:x.size||0,where:'OneDrive',url:x['@microsoft.graph.downloadUrl']||'',id:x.id,dir:folderPath()};
  }else if(kind==='path'){
    const t=await delegatedToken();
    const r=await fetch('https://graph.microsoft.com/v1.0/me/drive/root:/'+livePath().split('/').map(encodeURIComponent).join('/'),{headers:{Authorization:'Bearer '+t},signal:AbortSignal.timeout(30000)});
    const j=await r.json().catch(()=>({}));
    if(r.status===404)throw new Error('The '+K.what+' file was not found in your OneDrive: '+livePath());
    if(!r.ok)throw new Error('Could not read the '+K.what+' file: '+((j.error&&(j.error.message||j.error.code))||r.status));
    m={name:j.name,modified:j.lastModifiedDateTime||'',size:j.size||0,where:'OneDrive',url:j['@microsoft.graph.downloadUrl']||'',id:j.id,dir:livePath().split('/').slice(0,-1).join('/')};
  }else if(kind==='link'){
    const f=await fetchWorkbook(cfg(K.link));
    const mod=f.modified||crypto.createHash('sha1').update(f.buf).digest('hex').slice(0,12);
    S.buf=f.buf;S.mod=mod;m={name:f.name,modified:mod,size:f.buf.length,where:'OneDrive'};
  }else throw Object.assign(new Error('NOT_CONFIGURED'),{});
  S.meta=m;S.at=Date.now();return m;
}
async function liveFile(){
  const m=await liveMeta(false);
  if(S.buf&&S.mod===m.modified)return{buf:S.buf,meta:m};
  let buf;
  if(liveKind()==='local')buf=fs.readFileSync(localPick());
  else{
    let url=m.url;
    if(!url){const m2=await liveMeta(true);url=m2.url}
    const r=await fetch(url,{signal:AbortSignal.timeout(180000)});if(!r.ok)throw new Error('Download failed (HTTP '+r.status+')');
    buf=Buffer.from(await r.arrayBuffer());
  }
  if(buf.length<4||buf[0]!==0x50||buf[1]!==0x4b)throw new Error('The '+K.what+' file is not a readable Excel workbook.');
  S.buf=buf;S.mod=m.modified;return{buf,meta:m};
}
  return{kind:liveKind,meta:liveMeta,file:liveFile};
}
const LV=mkRemote({local:'LIVE_LOCAL_FILE',link:'ONEDRIVE_LIVE_LINK',file:'ONEDRIVE_LIVE_FILE',def:LIVE_DEFAULT,what:'live'});
const CM=mkRemote({local:'CAMS_LOCAL_FILE',lfolder:'CAMS_LOCAL_FOLDER',link:'ONEDRIVE_CAMS_LINK',file:'ONEDRIVE_CAMS_FILE',folder:'ONEDRIVE_CAMS_FOLDER',fdef:'CCDM/CAMS_Report',def:'CCDM/CCDM_Monitoring.xlsx',what:'CAMS'});
const liveKind=LV.kind,liveMeta=LV.meta,liveFile=LV.file;
const liveErr=(res,e)=>e.message==='NOT_CONNECTED'?json(res,409,{error:'Not signed in to OneDrive. Open the main page and click Connect OneDrive once.',connect:true}):json(res,502,{error:e.message});

// ---- CAMS Report: save the edits made in the web app into the monitoring workbook in OneDrive ----
const httpErr=(code,msg,extra)=>Object.assign(new Error(msg),{code,extra:extra||{}});
const encPath=p=>p.split('/').map(encodeURIComponent).join('/');
async function camsWriteBack(me){
  if(CM.kind()!=='path')throw httpErr(400,'Saving works only when the server is signed in to OneDrive (Connect OneDrive). A public link or a local folder cannot be written to.');
  const row=q.getDoc.get('cams/edits'),items=row?(JSON.parse(row.body).items||[]):[];
  if(!items.length)throw httpErr(400,'There are no edits to save.');
  const m=await CM.meta(true);
  if(!m.id)throw httpErr(502,'Could not identify the workbook in OneDrive.');
  if(!/\.xlsx$/i.test(m.name))throw httpErr(400,'Saving is built for .xlsx workbooks, and '+m.name+' is a different type.');
  const f=await CM.file(),r=xlApply(f.buf,items);
  if(!r.applied.length)return{saved:0,skipped:r.skipped,file:m.name};
  const t=await delegatedToken(),H={Authorization:'Bearer '+t},XL='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
  const reconnect=()=>httpErr(403,'OneDrive has not allowed this server to save yet. Click Connect OneDrive once more and accept the read and write permission.',{reconnect:true});
  // 1. a dated copy of the workbook as it is now (so nothing can be lost)
  const stamp=new Date().toISOString().slice(0,16).replace(/[-:T]/g,''),bpath=(m.dir?m.dir+'/':'')+'backups/'+m.name.replace(/\.xlsx$/i,'')+'-before-'+stamp+'.xlsx';
  const bk=await fetch('https://graph.microsoft.com/v1.0/me/drive/root:/'+encPath(bpath)+':/content',{method:'PUT',headers:Object.assign({'Content-Type':XL},H),body:f.buf,signal:AbortSignal.timeout(180000)});
  if(bk.status===401||bk.status===403)throw reconnect();
  if(!bk.ok)throw httpErr(502,'Could not save the backup copy to OneDrive (HTTP '+bk.status+'). Nothing was changed.');
  // 2. make sure nobody changed the workbook while we were working
  const m2=await CM.meta(true);
  if(m2.modified!==m.modified)throw httpErr(409,'The workbook was changed in OneDrive just now. Nothing was written; click Save again.');
  const up=await fetch('https://graph.microsoft.com/v1.0/me/drive/items/'+encodeURIComponent(m.id)+'/content',{method:'PUT',headers:Object.assign({'Content-Type':XL},H),body:r.buf,signal:AbortSignal.timeout(180000)});
  if(up.status===401||up.status===403)throw reconnect();
  if(up.status===423)throw httpErr(423,'The workbook is open or locked in OneDrive. Close it in Excel and click Save again. Nothing was changed.');
  if(!up.ok)throw httpErr(502,'OneDrive did not accept the new file (HTTP '+up.status+'). Nothing was changed.');
  // 3. the saved edits now live in the workbook: take them out of the list, keep the ones that could not be applied
  const keep=items.filter((_,i)=>!r.applied.includes(i)),lg=q.getDoc.get('cams/editlog'),rows=lg?(JSON.parse(lg.body).rows||[]):[];
  rows.unshift({at:new Date().toISOString(),by:me.username,txt:'Saved '+r.applied.length+' edit'+(r.applied.length===1?'':'s')+' into '+m.name+' in OneDrive (backup: '+bpath+')'+(r.skipped.length?'; '+r.skipped.length+' could not be applied':'')});
  q.setDoc.run('cams/edits',JSON.stringify({items:keep}),Date.now());q.setDoc.run('cams/editlog',JSON.stringify({rows:rows.slice(0,200)}),Date.now());
  await CM.meta(true);
  return{saved:r.applied.length,skipped:r.skipped.map(x=>Object.assign({},x,{what:items[x.ix]&&items[x.ix].sh})),file:m.name,backup:bpath};
}

// ---- OneDrive folder: one workbook per month ----
const MON=['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
function monthOf(name){let m=name.match(/(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[A-Z]*[ _\-.]*(20\d\d)/i);if(m)return m[2]+'-'+String(MON.indexOf(m[1].toUpperCase())+1).padStart(2,'0');
  m=name.match(/(20\d\d)[ _\-.]?(0[1-9]|1[0-2])(?!\d)/);return m?m[1]+'-'+m[2]:''}
let FOLDER_CACHE={at:0,items:[]};
function listLocal(dir){
  let names;try{names=fs.readdirSync(dir)}catch(e){throw new Error('Cannot open the folder '+dir+' ('+(e.code==='ENOENT'?'it does not exist':e.message)+'). Check LOCAL_FOLDER in data/config.json.')}
  const items=[];
  names.forEach(n=>{if(!/\.(xlsm|xlsx)$/i.test(n)||n.startsWith('~$'))return;let st;try{st=fs.statSync(path.join(dir,n))}catch(e){return}if(!st.isFile())return;
    items.push({id:n,name:n,month:monthOf(n),modified:st.mtime.toISOString(),file:path.join(dir,n)})});
  items.sort((a,b)=>(b.month||'').localeCompare(a.month||'')||(b.modified||'').localeCompare(a.modified||''));
  return items;
}
async function listFolder(force){
  if(cfg('LOCAL_FOLDER'))return listLocal(cfg('LOCAL_FOLDER')); // a folder on this PC (for example a synced OneDrive folder)
  const link=cfg('ONEDRIVE_FOLDER'),dpath=cfg('ONEDRIVE_PATH');
  if(!link&&!(delegated()&&dpath))throw new Error('No OneDrive folder is set on the server.');
  if(!force&&Date.now()-FOLDER_CACHE.at<60000)return FOLDER_CACHE.items;
  const enc=b64u(link),host=(()=>{try{return new URL(link).hostname}catch(e){return ''}})(),graph=cfg('MS_CLIENT_ID')&&cfg('MS_CLIENT_SECRET')&&cfg('MS_TENANT_ID');
  let url,headers={};
  if(delegated()&&dpath){url='https://graph.microsoft.com/v1.0/me/drive/root:/'+dpath.replace(/^\/+|\/+$/g,'').split('/').map(encodeURIComponent).join('/')+':/children?$top=200';headers={Authorization:'Bearer '+await delegatedToken()}}
  else if(graph){url='https://graph.microsoft.com/v1.0/shares/u!'+enc+'/driveItem/children?$top=200';headers={Authorization:'Bearer '+await graphToken()}}
  else if(/(^|\.)(1drv\.ms|onedrive\.live\.com)$/.test(host))url='https://api.onedrive.com/v1.0/shares/u!'+enc+'/root/children?$top=200';
  else throw new Error('A SharePoint / work OneDrive folder cannot be listed with a public link. Ask your IT admin for the app details (see README, "Private").');
  const items=[];
  for(let pages=0;url&&pages<10;pages++){
    const r=await fetch(url,{headers,signal:AbortSignal.timeout(30000)}),j=await r.json().catch(()=>({}));
    if(!r.ok&&delegated()&&r.status===404)throw new Error('The folder path was not found in your OneDrive: '+dpath);
    if(!r.ok)throw new Error('Could not open the folder: '+((j.error&&(j.error.message||j.error.code))||r.status)+'. Is the folder shared as "Anyone with the link can view"?');
    (j.value||[]).forEach(v=>{if(v.file&&/\.(xlsm|xlsx)$/i.test(v.name)&&!v.name.startsWith('~$'))items.push({id:v.id,name:v.name,month:monthOf(v.name),modified:v.lastModifiedDateTime||'',url:v['@microsoft.graph.downloadUrl']||v['@content.downloadUrl']||''})});
    url=j['@odata.nextLink']||null;
  }
  items.sort((a,b)=>(b.month||'').localeCompare(a.month||'')||(b.modified||'').localeCompare(a.modified||''));
  FOLDER_CACHE={at:Date.now(),items};return items;
}

const SESSION_MS=1000*60*60*12;
const IDLE_MIN=Math.max(0,Number(process.env.IDLE_TIMEOUT_MIN==null||process.env.IDLE_TIMEOUT_MIN===''?30:process.env.IDLE_TIMEOUT_MIN)||0); // sign out after this many idle minutes (0 = never)
const cookie=(req)=>Object.fromEntries((req.headers.cookie||'').split(';').map(s=>s.trim().split('=')).filter(a=>a[0]).map(a=>[a[0],a.slice(1).join('=')]));
function authed(req){q.purge.run(Date.now());const t=cookie(req).sid;return t?q.sess.get(t,Date.now())||null:null}
const secure=(req)=>req.headers['x-forwarded-proto']==='https'||req.socket.encrypted;
const send=(res,code,body,type,extra)=>{res.writeHead(code,Object.assign({'Content-Type':type||'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','X-Frame-Options':'SAMEORIGIN','Referrer-Policy':'same-origin'},extra||{}));res.end(typeof body==='string'||Buffer.isBuffer(body)?body:JSON.stringify(body))};
const json=(res,code,o)=>send(res,code,o);
function body(req,limit=1500000){return new Promise((ok,no)=>{let n=0,c=[];req.on('data',d=>{n+=d.length;if(n>limit){no(new Error('too large'));req.destroy()}else c.push(d)});req.on('end',()=>ok(Buffer.concat(c).toString('utf8')));req.on('error',no)})}
const fails=new Map(); // login throttling per ip+user
function throttled(k){const f=fails.get(k);return f&&f.n>=5&&Date.now()<f.until}
function noteFail(k){const f=fails.get(k)||{n:0,until:0};f.n++;if(f.n>=5)f.until=Date.now()+5*60*1000;fails.set(k,f)}
const PATH_OK=/^[A-Za-z0-9_\-.~:@+]{1,200}(\/[A-Za-z0-9_\-.~:@+]{1,200}){0,6}$/;
// Pages are read from public/ if present; otherwise the copy embedded at the bottom of this file is used.
const asset=f=>{try{return fs.readFileSync(path.join(__dirname,'public',f))}catch(e){if(EMBED[f])return Buffer.from(EMBED[f],'base64');throw e}};
const page=f=>asset(f).toString('utf8');
const sameOrigin=(req)=>{const o=req.headers.origin;return !o||new URL(o).host===req.headers.host};

const server=http.createServer(async(req,res)=>{
  try{
    const url=new URL(req.url,'http://x'),p=url.pathname,me=authed(req);
    if(req.method!=='GET'&&!sameOrigin(req))return json(res,403,{error:'bad origin'});

    if(p==='/login'&&req.method==='GET')return send(res,200,page('login.html'),'text/html; charset=utf-8');
    if(p==='/api/login'&&req.method==='POST'){
      const d=JSON.parse(await body(req,5000)||'{}'),k=req.socket.remoteAddress+'|'+String(d.username||'').toLowerCase();
      if(throttled(k))return json(res,429,{error:'Too many attempts. Try again in a few minutes.'});
      const u=q.userBy.get(String(d.username||''));
      if(!u||!checkPw(u,String(d.password||''))){noteFail(k);return json(res,401,{error:'Wrong username or password.'})}
      fails.delete(k);const t=crypto.randomBytes(32).toString('base64url');q.addSess.run(t,u.id,Date.now()+SESSION_MS);
      return send(res,200,{ok:true},null,{'Set-Cookie':`sid=${t}; HttpOnly; SameSite=Lax; Path=/; Max-Age=${SESSION_MS/1000}${secure(req)?'; Secure':''}`});
    }
    if(p==='/api/logout'&&req.method==='POST'){const t=cookie(req).sid;if(t)q.delSess.run(t);return send(res,200,{ok:true},null,{'Set-Cookie':'sid=; HttpOnly; Path=/; Max-Age=0'})}

    if(p==='/auth/callback'&&req.method==='GET'){ // no session cookie needed: Microsoft returns here, possibly on a different host name
      const st=url.searchParams.get('state'),ver=PENDING.get(st);PENDING.delete(st);
      const page=(t,ok)=>send(res,200,`<!doctype html><meta charset=utf-8><body style="font:16px system-ui;padding:40px;max-width:520px;margin:auto"><h2>${ok?'OneDrive connected':'Could not connect'}</h2><p>${t}</p>`,'text/html; charset=utf-8');
      if(!ver||!url.searchParams.get('code'))return page('The sign-in was cancelled or expired. '+(url.searchParams.get('error_description')||'Go back to the billing page and click Connect OneDrive again.').replace(/[<>&]/g,''),false);
      try{await tokenCall({grant_type:'authorization_code',code:url.searchParams.get('code'),redirect_uri:REDIRECT(),code_verifier:ver});FOLDER_CACHE.at=0;return page('You can close this tab and go back to the billing page. It will pick up your files.',true)}
      catch(e){return page(String(e.message).replace(/[<>&]/g,''),false)}
    }
    if(!me){ if(p.startsWith('/api/'))return json(res,401,{error:'signed out'}); res.writeHead(302,{Location:'/login'});return res.end()}

    if(p==='/'||p==='/index.html'){ // the app, with the server connector injected before its own script
      let h=page('app.html');const i=h.indexOf('<script>');h=h.slice(0,i)+'<script src="/shim.js"></script>\n'+h.slice(i);
      return send(res,200,h,'text/html; charset=utf-8')}
    if(p==='/live'&&req.method==='GET'){ // the Live window: every signed-in user (bank limits apply to Billing only)
      let h=page('live.html');const i=h.indexOf('<script>');h=h.slice(0,i)+'<script src="/shim.js"></script>\n'+h.slice(i);
      return send(res,200,h,'text/html; charset=utf-8')}
    if(p==='/api/live/info'&&req.method==='GET'){
      if(!liveKind())return json(res,200,{configured:false});
      try{const m=await liveMeta(false);return json(res,200,{configured:true,name:m.name,modified:m.modified,size:m.size,where:m.where})}
      catch(e){return liveErr(res,e)}
    }
    if(p==='/api/live/file'&&req.method==='GET'){
      try{const f=await liveFile();return send(res,200,f.buf,'application/octet-stream',{'X-File-Name':encodeURIComponent(f.meta.name),'X-Last-Modified':f.meta.modified})}
      catch(e){return liveErr(res,e)}
    }
    if(p==='/api/cams/writeback'&&req.method==='POST'){
      if(me.role!=='admin')return json(res,403,{error:'Only the publisher can save to OneDrive.'});
      try{return json(res,200,await camsWriteBack(me))}catch(e){return json(res,typeof e.code==='number'?e.code:502,Object.assign({error:e.message},e.extra||{}))}
    }
    if(p==='/api/cams/info'&&req.method==='GET'){
      if(!tabsOf(me).includes('CAMS'))return json(res,403,{error:'not allowed'});
      if(!CM.kind())return json(res,200,{configured:false});
      try{const m=await CM.meta(false);return json(res,200,{configured:true,name:m.name,modified:m.modified,size:m.size,where:m.where})}
      catch(e){return liveErr(res,e)}
    }
    if(p==='/api/cams/file'&&req.method==='GET'){
      if(!tabsOf(me).includes('CAMS'))return json(res,403,{error:'not allowed'});
      try{const f=await CM.file();return send(res,200,f.buf,'application/octet-stream',{'X-File-Name':encodeURIComponent(f.meta.name),'X-Last-Modified':f.meta.modified})}
      catch(e){return liveErr(res,e)}
    }
    if(p==='/shim.js')return send(res,200,asset('shim.js'),'application/javascript; charset=utf-8');
    if(p==='/users')return me.role==='admin'?send(res,200,page('users.html'),'text/html; charset=utf-8'):(res.writeHead(302,{Location:'/'}),res.end());

    if(p==='/auth/login'&&req.method==='GET'){
      if(me.role!=='admin'||!delegated())return json(res,403,{error:'not allowed'});
      const ver=crypto.randomBytes(32).toString('base64url'),st=crypto.randomBytes(16).toString('hex');PENDING.set(st,ver);setTimeout(()=>PENDING.delete(st),600000);
      const ch=crypto.createHash('sha256').update(ver).digest('base64url');
      const u=AUTHORITY()+'/authorize?'+new URLSearchParams({client_id:cfg('MS_CLIENT_ID'),response_type:'code',redirect_uri:REDIRECT(),response_mode:'query',scope:'offline_access Files.ReadWrite',state:st,code_challenge:ch,code_challenge_method:'S256'});
      res.writeHead(302,{Location:u});return res.end();
    }
    if(p==='/api/source'&&req.method==='GET')return json(res,200,{configured:me.role==='admin'&&!!(cfg('LOCAL_FOLDER')||cfg('ONEDRIVE_FOLDER')||cfg('ONEDRIVE_LINK')||(delegated()&&cfg('ONEDRIVE_PATH'))),folder:!!(cfg('LOCAL_FOLDER')||cfg('ONEDRIVE_FOLDER')||(delegated()&&cfg('ONEDRIVE_PATH'))),connect:delegated()&&!!cfg('ONEDRIVE_PATH')&&!loadTok()});
    if(p==='/api/source/list'&&req.method==='GET'){
      if(me.role!=='admin')return json(res,403,{error:'Only the publisher can load the database.'});
      try{return json(res,200,(await listFolder(url.searchParams.get('force')==='1')).map(x=>({id:x.id,name:x.name,month:x.month,modified:x.modified})))}catch(e){return json(res,e.message==='NOT_CONNECTED'?409:502,{error:e.message==='NOT_CONNECTED'?'Not connected to OneDrive yet.':e.message,connect:e.message==='NOT_CONNECTED'})}
    }
    if(p==='/api/source/file'&&url.searchParams.get('id')){
      if(me.role!=='admin')return json(res,403,{error:'Only the publisher can load the database.'});
      try{
        let it=(await listFolder(false)).find(x=>x.id===url.searchParams.get('id'));if(!it)it=(await listFolder(true)).find(x=>x.id===url.searchParams.get('id'));
        if(!it||(!it.url&&!it.file))throw new Error('That file was not found in the folder.');
        let data;
        if(it.file)data=fs.readFileSync(it.file); // OneDrive downloads a cloud-only file when it is opened
        else{const r=await fetch(it.url,{signal:AbortSignal.timeout(180000)});if(!r.ok)throw new Error('Download failed (HTTP '+r.status+')');data=Buffer.from(await r.arrayBuffer())}
        return send(res,200,data,'application/octet-stream',{'X-File-Name':encodeURIComponent(it.name),'X-Last-Modified':it.modified})
      }catch(e){return json(res,502,{error:e.message})}
    }
    if(p==='/api/source/file'&&req.method==='GET'){
      if(me.role!=='admin')return json(res,403,{error:'Only the publisher can load the database.'});
      try{const f=await fetchWorkbook();return send(res,200,f.buf,'application/octet-stream',{'X-File-Name':encodeURIComponent(f.name),'X-Last-Modified':f.modified})}
      catch(e){return json(res,502,{error:e.message})}
    }
    if(p==='/api/me'){const A=allowedBanks(me);return json(res,200,{id:me.id,username:me.username,role:me.role,banks:A?[...A]:[],tabs:tabsOf(me),cams:tabsOf(me).includes('CAMS'),idleMin:me.role==='admin'?0:IDLE_MIN})}
    if(p==='/api/doc'){
      const dp=url.searchParams.get('path')||'';if(!PATH_OK.test(dp))return json(res,400,{error:'bad path'});
      if(req.method==='GET'){
        const A=allowedBanks(me);
        if(A&&!docAllowed(dp,A))return json(res,403,{error:'You do not have access to this bank.'});
        if(/^cams\//.test(dp)&&!tabsOf(me).includes('CAMS'))return json(res,403,{error:'not allowed'}); // CAMS edits are only for people who may open the CAMS Report
        const r=q.getDoc.get(dp);if(!r)return json(res,200,{exists:false});
        let data=JSON.parse(r.body);if(A&&/(^|\/)results\/current$/.test(dp))data=filterResults(data,A);
        return json(res,200,{exists:true,data:data,updated:r.updated})}
      if(me.role!=='admin')return json(res,403,{error:'Only the publisher can change shared results.'});
      if(req.method==='PUT'){const b=await body(req);JSON.parse(b);q.setDoc.run(dp,b,Date.now());return json(res,200,{ok:true})}
      if(req.method==='DELETE'){q.delDoc.run(dp);return json(res,200,{ok:true})}
    }
    if(p.startsWith('/api/users')){
      if(me.role!=='admin')return json(res,403,{error:'admins only'});
      if(req.method==='GET'&&p==='/api/users')return json(res,200,q.users.all());
      if(req.method==='POST'&&p==='/api/users'){const d=JSON.parse(await body(req,5000));const n=String(d.username||'').trim(),pw=String(d.password||'');
        if(!/^[A-Za-z0-9_.@-]{2,40}$/.test(n))return json(res,400,{error:'Username: 2-40 letters, numbers or . _ @ -'});if(pw.length<8)return json(res,400,{error:'Password must be at least 8 characters.'});
        try{addUser(n,pw,d.role==='admin'?'admin':'viewer',d.banks)}catch(e){return json(res,400,{error:'That username already exists.'})}return json(res,200,{ok:true})}
      const m=p.match(/^\/api\/users\/(\d+)$/);
      if(m){const u=q.userId.get(+m[1]);if(!u)return json(res,404,{error:'no such user'});
        if(req.method==='PUT'){const d=JSON.parse(await body(req,5000));
          if(d.banks!==undefined&&u.role!=='admin')q.setBanks.run(cleanBanks(d.banks),u.id);
          if(d.tabs!==undefined&&u.role!=='admin')q.setTabs.run(cleanTabs(d.tabs),u.id);
          if(d.password!==undefined){if(String(d.password).length<8)return json(res,400,{error:'Password must be at least 8 characters.'});setPassword(u.id,String(d.password))}
          return json(res,200,{ok:true})}
        if(req.method==='DELETE'){if(u.id===me.id)return json(res,400,{error:'You cannot delete your own account.'});if(u.role==='admin'&&q.admins.get().n<2)return json(res,400,{error:'Keep at least one admin.'});q.delUserSess.run(u.id);q.delUser.run(u.id);return json(res,200,{ok:true})}}
    }
    json(res,404,{error:'not found'});
  }catch(e){json(res,400,{error:e.message})}
});
const up=()=>console.log(`ESI CCDM Billing running on http://localhost:${PORT}`);
server.on('error',e=>{
  if(HOST==='::'&&(e.code==='EAFNOSUPPORT'||e.code==='EADDRNOTAVAIL')){server.listen(PORT,'0.0.0.0',up);return} // no IPv6 on this PC
  if(e.code==='EADDRINUSE'){console.log(`\n  Port ${PORT} is already in use. Close the other copy, or start with a different port:  PORT=3001 node server.js\n`);process.exit(1)}
  throw e});
server.listen(PORT,HOST,up);

